Result<int, string> Produce(int minerals) =>
    minerals >= 50
        ? new Result<int, string>.Success(minerals - 50)
        : new Result<int, string>.Failure("미네랄 부족");

foreach (int m in new[] { 80, 30 })
{
    string msg = Produce(m) switch
    {
        Result<int, string>.Success s => "마린 생산! 남은 미네랄 " + s.Data,
        Result<int, string>.Failure f => "실패: " + f.Error,
        _ => "?",
    };
